.cu-chip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--cu-space-1);
  padding-block: calc(var(--cu-space-1) / 2);
  padding-inline: var(--cu-space-2);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-md);
  font: inherit;
  font-size: 0.875rem;
  color: var(--cu-color-fg-default);
  background: var(--cu-color-background-default);
}

.cu-chip--primary {
  color: var(--cu-color-fg-inverse);
  background: var(--cu-color-palette-brand);
  border-color: transparent;
}

.cu-chip--success {
  color: var(--cu-color-fg-inverse);
  background: color-mix(in srgb, var(--cu-color-palette-brand) 70%, #16a34a);
  border-color: transparent;
}

.cu-chip--warning {
  color: var(--cu-color-fg-default);
  background: #f59e0b;
  border-color: transparent;
}

.cu-chip--danger {
  color: var(--cu-color-fg-inverse);
  background: #dc2626;
  border-color: transparent;
}

.cu-chip__remove {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: 1.25rem;
  block-size: 1.25rem;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: transparent;
  color: inherit;
  cursor: pointer;
  font-weight: 700;
}

.cu-chip__remove:focus-visible {
  outline: 2px solid var(--cu-color-palette-brand);
  outline-offset: 2px;
}
